  tools.exec_command({cmd:"rtk proxy pwd",max_output_tokens:1000}),
  tools.exec_command({cmd:"rtk proxy rg -n \"typst|live-voice-relay|playwright|TWYNE_DEV_PORT\" /home/diogenes/.codex/memories/MEMORY.md",max_output_tokens:5000})
]);
for (let i=0;i<results.length;i++) text({i,...results[i]});
text(ALL_TOOLS.filter(x=>/agent|spawn|delegate/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,180)})));

const rs=await Promise.allSettled([
tools.exec_command({cmd:"rtk proxy git status --short",max_output_tokens:6000}),
tools.exec_command({cmd:"rtk proxy git diff -- src/utils/typst/document.ts src/utils/typst/document.test.ts scripts/live-voice-relay.mjs tests/live-voice-relay.test.ts playwright.config.ts",max_output_tokens:16000}),
