tools.exec_command({cmd:"rtk proxy sed -n '5790,5822p' /home/diogenes/.codex/memories/MEMORY.md",max_output_tokens:3500})
]);rs.forEach((x,i)=>text({i,...x}));
text(ALL_TOOLS.filter(x=>/search|skill|task|parallel|worker|subagent|spawn/i.test(x.name)).map(x=>({name:x.name,description:x.description.slice(0,120)})));

