{
  "name": "twyne",
  "description": "Twyne — The writer's room, AI-powered editing with a room full of editors",
  "engines": {
    "node": "^20.19.0 || >=22.12.0"
  },
  "engines-annotation": "Mostly required by sharp which needs a Node-API v9 compatible runtime",
  "private": true,
  "type": "module",
  "version": "0.22.0",
  "packageManager": "bun@1.3.6",
  "scripts": {
    "i18n:package": "bun run --cwd packages/gt-qwik build",
    "i18n:compile": "bun scripts/compile-i18n.ts",
    "i18n:check": "gt translate --dry-run",
    "i18n:translate": "gt translate && bun run i18n:compile",
    "build": "bun run i18n:prepare && TWYNE_I18N_PREPARED=1 qwik build",
    "build.client": "bun run i18n:prepare && vite build",
    "build.preview": "bun run i18n:prepare && vite build --ssr src/entry.preview.tsx",
    "build.types": "bun run i18n:prepare && tsc --incremental --noEmit",
    "build.server": "bun run i18n:prepare && vite build --ssr src/entry.preview.tsx",
    "deploy": "bun run build.client && bun run build.server && bun server.js",
    "preversion": "bun run release:check",
    "postversion": "bun run release:check",
    "release:check": "bun scripts/check-release-version.ts",
    "release:version": "bun pm version",
    "release:publish": "git push --follow-tags",
    "desktop": "electrobun dev && electrobun run",
    "desktop.build": "electrobun build",
    "dev": "bun run i18n:prepare && concurrently --names \"CONVEX,VITE\" --prefix-colors cyan,magenta \"npx convex dev\" \"vite --mode ssr\"",
    "dev.frontend": "bun run i18n:prepare && vite --mode ssr --host 127.0.0.1 --port ${TWYNE_DEV_PORT:-5173} --strictPort",
    "dev.backend": "npx convex dev",
    "dev.debug": "node --inspect-brk ./node_modules/vite/bin/vite.js --mode ssr --force",
    "fmt": "prettier --write .",
    "fmt.check": "prettier --check .",
    "lint": "eslint \"src/**/*.ts*\"",
    "preview": "bun run i18n:prepare && TWYNE_I18N_PREPARED=1 qwik build preview && vite preview --open",
    "start": "bun run i18n:prepare && vite --open --mode ssr",
    "serve": "node server.js",
    "storybook": "storybook dev --host 127.0.0.1 -p ${TWYNE_STORYBOOK_PORT:-6006} --ci",
    "storybook.build": "storybook build",
    "test": "bun run i18n:prepare && bun test --conditions=production --preload ./tests/qwik-test-preload.ts",
    "tools:build": "bun run --cwd packages/twyne-tools build",
    "tools:check": "bun run --cwd packages/twyne-tools check",
    "tools:test": "bun --cwd packages/twyne-tools test",
    "test:e2e": "playwright test",
    "ci": "dagger call all",
    "ci.test": "dagger call test",
