  const wss = new WebSocketServer({
    noServer: true,
    maxPayload: FRAME,
    perMessageDeflate: false,
  });
  const issuer =
    options.issuer ??
    process.env.NOTORGANIC_ISSUER ??
    "https://api.notorganic.info";
