      const tail = contentSource.slice(value.end);
      const imageOptions = /^,\s*width:\s*[\d.]+%,\s*alt:\s*/.exec(tail);
      if (!imageOptions) throw new Error("Unsupported image arguments");
      const alt = quoted(tail, imageOptions[0].length);
