  return {
    url: url.href,
    headers: {
      authorization: value.authorization,
      dpop: value.dpop,
      "idempotency-key": value.idempotencyKey,
      "x-notorganic-max-cost-microusd": "500000",
      "x-notorganic-product": "twyne",
      "x-notorganic-feature": "voice-live",
    },
  };
}

