          return fail("Live is not ready or the connection is too slow.");
        upstream.send(raw.toString());
      });
    });
  };
  server.on("upgrade", upgrade);
  return () => {
    server.off("upgrade", upgrade);
    for (const client of wss.clients) client.close();
    wss.close();
  };
}
