      };
      const fail = (message) => {
        if (client.readyState === WebSocket.OPEN)
          client.send(JSON.stringify({ type: "twyne.live.error", message }));
        close();
      };
      const deadline = setTimeout(
        () => fail("Live connection timed out. Try again."),
        15_000,
