          upstream = new WebSocket(auth.url, {
            headers: auth.headers,
            handshakeTimeout: 12_000,
            maxPayload: FRAME,
            followRedirects: false,
            perMessageDeflate: false,
          });
          upstream.on("open", () => {
            if (phase === "closed") {
              upstream.close();
              return;
            }
            phase = "open";
            clearTimeout(deadline);
            lifetime = setTimeout(
              () => fail("Live reached its session limit."),
              26 * 60_000,
            );
